Given
template<typename Policy>
double price(double x) {
    return Policy().apply(x);
}
adding `struct Student { double apply(double x) { return x * 0.9; } };` extends pricing with zero edits to `price()` — which SOLID principle does this static polymorphism serve?

Given
class Rectangle {
    int w, h;
    void setWidth(int x) {
        w = x;
    }
    void setHeight(int x) {
        h = x;
    }
    int area() {
        return w * h;
    }
}
class Square extends Rectangle {
    void setWidth(int x) {
        w = h = x;
    }
    void setHeight(int x) {
        w = h = x;
    }
}
Rectangle r = new Square();
r.setWidth(5);
r.setHeight(2);
what does `r.area()` return?
